import { useEffect, useState } from "react";
import { useParams, Link } from "react-router-dom";
import { api, formatApiError } from "../lib/api";
import { useAuth } from "../lib/auth";
import { toast } from "sonner";
import LoadingSpinner from "../components/LoadingSpinner";
import { fetchLore } from "../api/lore";
import CommentThread from "../components/CommentThread";
import AuthPromptDialog from "../components/AuthPromptDialog";

export default function LoreEntry() {
  const { id } = useParams();
  const { user } = useAuth();
  const [l, setL] = useState(null);
  const [voteLoading, setVoteLoading] = useState(false);
  const [authPromptOpen, setAuthPromptOpen] = useState(false);

  useEffect(() => {
    fetchLore(id).then((r) => setL(r.data));
  }, [id]);

  const voteLore = async () => {
    if (!user) return;
    setVoteLoading(true);
    try {
      const r = await api.post(`/lore/${id}/vote`);
      setL(r.data);
      toast.success("voted");
    } catch (e) {
      toast.error(formatApiError(e.response?.data?.detail));
    } finally {
      setVoteLoading(false);
    }
  };

  if (!l) return <div className="px-6 py-20 meta-ink">loading...</div>;

  return (
    <article className="max-w-3xl mx-auto px-6 py-16">
      <div className="meta-ink mb-3">
        lore entry / {l.depth} read / by{" "}
        <Link to={`/c/${l.author}`} className="underline">
          @{l.author}
        </Link>
      </div>
      <h1 className="font-display font-black text-4xl md:text-6xl tracking-tighter leading-[0.95]" data-testid="lore-title">
        {l.title}
      </h1>
      <div className="flex flex-wrap gap-3 mt-5 items-center">
        {l.track_id && <Link to={`/track/${l.track_id}`} className="tag-chip">track / {l.track_id}</Link>}
        {l.album_id && <Link to={`/album/${l.album_id}`} className="tag-chip">album / {l.album_id}</Link>}
        <span className="tag-chip">{l.votes || 0} votes</span>
        {user ? (
          <button
            className="brutal-btn accent"
            type="button"
            disabled={voteLoading}
            onClick={voteLore}
          >
            {voteLoading ? <><LoadingSpinner size={16} /> <span className="ml-2">Voting</span></> : "upvote"}
          </button>
        ) : (
          <button type="button" className="brutal-btn accent" onClick={() => setAuthPromptOpen(true)}>
            log in to vote
          </button>
        )}
        <AuthPromptDialog open={authPromptOpen} onClose={() => setAuthPromptOpen(false)} />
      </div>
      <div className="mt-10 editorial-prose dropcap" data-testid="lore-body">
        {(l.body || l.excerpt || "").split("\n\n").map((p, i) => (
          <p key={i}>{p}</p>
        ))}
      </div>
      <CommentThread targetType="lore" targetId={l.id} initialCount={l.comments || 0} />
    </article>
  );
}
